INSERT INTO `settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('page_about', '{"greeting_badge":"Lời chào từ Phòng Khám VIP","main_title":"Đồng Hành Cùng Sức Khỏe Gia Đình Bạn","lead_text":"Chào mừng Quý khách đến với Phòng Khám VIP. Chúng tôi vinh hạnh được là người bạn đồng hành tin cậy trên hành trình chăm sóc và bảo vệ sức khỏe cho bạn cùng những người thân yêu.","mission_title":"Sứ Mệnh Của Chúng Tôi","mission_desc":"Mang đến dịch vụ y tế toàn diện, chuẩn mực và nhân văn. Chúng tôi đặt y đức, sự an toàn và trải nghiệm thoải mái của bệnh nhân làm kim chỉ nam trong mọi hoạt động khám và điều trị.","values":"Tận Tâm, Chuyên Nghiệp, Hiện Đại, Trách Nhiệm, Hihi","image_url":"/images/about-portrait.png"}', '2026-08-31 15:59:55');
